query:
select b.v, st.v, eta.v, (select count(*) from "core/part_of" p where p.v = b.e) as lines
from "shipment/booking_no" b join "shipment/status" st using (e) left join "shipment/eta" eta using (e)
where st.v in ('departed','arrived') order by b.v

select f.a, count(distinct x.e) from (
  select e from "qc/report_no" union select e from "qc/inspected_on" union select e from "qc/result" union select e from "qc/po"
) x join facts f on f.e = x.e group by f.a
